import{_ as t,o as a,c as s,ah as n}from"./chunks/framework.ChH6X6u6.js";const u=JSON.parse('{"title":"Class changes","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/secretariat/changements-de-classe.md","filePath":"src/en/guide/secretariat/changements-de-classe.md"}'),r={name:"en/guide/secretariat/changements-de-classe.md"};function o(i,e,h,l,c,d){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="class-changes" tabindex="-1">Class changes <a class="header-anchor" href="#class-changes" aria-label="Permalink to &quot;Class changes&quot;">​</a></h1><p>A student sometimes needs to move to another class after being placed: a change of orientation in the first weeks (from 1ère C to 1ère D, for example), or a correction before class lists are final. The <strong>Class changes</strong> page, in the <strong>Students &amp; admissions</strong> space, is there for that. It is open to the secretariat and to administrators.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>A class change stays <strong>on the same site</strong> and <strong>within the same academic year</strong>. To move a student to another site, use a <a href="/era-guide/en/guide/secretariat/transferts-sites.html">site transfer</a>.</p></div><h2 id="moving-a-student-to-another-class" tabindex="-1">Moving a student to another class <a class="header-anchor" href="#moving-a-student-to-another-class" aria-label="Permalink to &quot;Moving a student to another class&quot;">​</a></h2><ol><li>In <strong>Student</strong>, type at least two letters of their first or last name, then click the student in the list. Only students enrolled in a running year (or one already prepared) appear.</li><li>Check their <strong>current class</strong>, shown with its department, site and year. If it is the wrong student, click <strong>Choose another student</strong>.</li><li>In <strong>New class</strong>, pick the destination. The list only offers classes on the same site and in the same year, with their headcount and capacity.</li><li>Add a <strong>Reason</strong> if you wish, for example &quot;moving to the D stream&quot;. It stays visible in the history.</li><li>Click <strong>Change class</strong>.</li></ol><p>The student&#39;s enrollment is moved, not recreated: their payments, payment plan and bulletins stay attached to their record.</p><h2 id="warnings-before-you-confirm" tabindex="-1">Warnings before you confirm <a class="header-anchor" href="#warnings-before-you-confirm" aria-label="Permalink to &quot;Warnings before you confirm&quot;">​</a></h2><p>Depending on the situation, a box appears under the chosen class:</p><ul><li><strong>Grades were already entered</strong> in the original class: they are not carried over and no longer count for the student. They are not deleted, though, and the number of abandoned grades is kept in the history.</li><li><strong>The class belongs to another department</strong>: check the student&#39;s options and fee schedule, which may differ.</li><li><strong>The class is full</strong>: the button stays disabled until you tick <strong>Place the student in this class anyway</strong>.</li></ul><h2 id="when-a-change-is-refused" tabindex="-1">When a change is refused <a class="header-anchor" href="#when-a-change-is-refused" aria-label="Permalink to &quot;When a change is refused&quot;">​</a></h2><ul><li>The chosen class is the one the student is already in.</li><li>The <strong>academic year is closed</strong>: no change is possible any more (see closing a year in the administrator guide).</li></ul><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><p>Below the form, the <strong>Change history</strong> lists every change: the date, the student, the original and destination classes with the year, the reason, and who made it. The number of abandoned grades appears when there were any.</p>',13)])])}const m=t(r,[["render",o]]);export{u as __pageData,m as default};
